/bin/bash -lc "sqlite3 -header -column 'file:assets/data/career_path.db?mode=ro' <<'SQL'
WITH RECURSIVE chain(id, slug, name, parent_id, breadcrumb) AS (
  SELECT id, slug, name, parent_id, name FROM career_nodes WHERE parent_id IS NULL
  UNION ALL
  SELECT c.id, c.slug, c.name, c.parent_id, chain.breadcrumb || ' > ' || c.name
  FROM career_nodes c JOIN chain ON c.parent_id=chain.id
)
SELECT id, slug, parent_id, breadcrumb FROM chain WHERE id IN (2,21,24,25,90,147,153,155,154,156,180,181,182,9,10,12,34,35,80,86) ORDER BY id;

SELECT id, slug, parent_id, name FROM career_nodes WHERE parent_id IN (2,21,24,25) ORDER BY parent_id,id;
SQL"

